package KindLists {
    // Definitions the usages below are typed by.
    part def P;
    item def It;
    occurrence def O;
    attribute def AT;
    enum def E { enum x; }
    port def Q;
    connection def Cn;
    interface def I;
    allocation def Al;
    flow def F;
    action def A;
    state def S;
    calc def C;
    case def K;
    analysis def An;
    verification def Vc;
    use case def U;
    constraint def Ct;
    requirement def R;
    concern def Cc;
    view def Vw;
    viewpoint def Vp;
    rendering def Rd;
    metadata def M;

    // One holder per kind: members of the kind, a member of a subkind, a member of another kind, and a
    // reference typed by the kind's definition (of the kind semantically, not by its metaclass).
    part def ForFeatures { part p : P; attribute a : AT; }
    part def ForUsages { part p : P; attribute a : AT; }
    part def ForActions { action a : A; state s : S; calc c : C; part p : P; ref r : A; }
    part def ForAllocations { allocation al : Al; part p : P; ref r : Al; }
    part def ForAnalysisCases { analysis an : An; part p : P; ref r : An; }
    part def ForAttributes { attribute a : AT; enum e : E; part p : P; ref r : AT; }
    part def ForCalculations { calc c : C; case k : K; action a : A; ref r : C; }
    part def ForCases { case k : K; use case u : U; calc c : C; ref r : K; }
    part def ForConcerns { concern cc : Cc; requirement rq : R; ref r : Cc; }
    part def ForConnections { connection c : Cn; interface i : I; part p : P; ref r : Cn; }
    part def ForConstraints { constraint ct : Ct; requirement rq : R; part p : P; ref r : Ct; }
    part def ForEnumerations { enum e : E; attribute a : AT; }
    part def ForFlows { flow f : F; succession flow sf : F; action a : A; ref r : F; }
    part def ForInterfaces { interface i : I; connection c : Cn; ref r : I; }
    part def ForItems { item it : It; part p : P; attribute a : AT; ref r : It; }
    part def ForMetadata { metadata md : M; part p : P; }
    part def ForOccurrences { occurrence o : O; part p : P; attribute a : AT; ref r : O; }
    part def ForParts { part p : P; connection c : Cn; item it : It; ref r : P; }
    part def ForPorts { port q : Q; part p : P; ref r : Q; }
    part def ForReferences { ref r : P; part p : P; }
    part def ForRenderings { rendering rd : Rd; part p : P; ref r : Rd; }
    part def ForRequirements { requirement rq : R; concern cc : Cc; constraint ct : Ct; ref r : R; }
    part def ForStates { state s : S; exhibit state es : S; action a : A; ref r : S; }
    state def ForTransitions { state off; state on; transition t first off then on; }
    use case def ForUseCases { use case uc : U; include use case iu : U; case k : K; ref r : U; }
    part def ForVerificationCases { verification v : Vc; part p : P; ref r : Vc; }
    part def ForViews { view vw : Vw; part p : P; ref r : Vw; }
    part def ForViewpoints { viewpoint vp : Vp; requirement rq : R; ref r : Vp; }
}

DefinitionLists.text:
package DefinitionLists {
    // One package per kind: definitions of the kind, of a subkind, of another kind, and a definition
    // of a more general kind that specializes one of the kind (of the kind semantically only).
    package ForDefinitions { part def P; attribute def AT; }
    package ForActionDefs { action def A; state def S; part def P; occurrence def X :> A; }
    package ForAllocationDefs { allocation def Al; part def P; connection def X :> Al; }
    package ForAnalysisCaseDefs { analysis def An; part def P; case def X :> An; }
    package ForAttributeDefs { attribute def AT; enum def E { enum x; } part def P; }
    package ForCalculationDefs { calc def C; case def K; action def A; action def X :> C; }
    package ForCaseDefs { case def K; use case def U; calc def C; calc def X :> K; }
    package ForConcernDefs { concern def Cc; requirement def R; requirement def X :> Cc; }
    package ForConnectionDefs { connection def Cn; interface def I; part def P; }
    package ForConstraintDefs { constraint def Ct; requirement def R; part def P; }
    package ForEnumerationDefs { enum def E { enum x; } attribute def AT; }
    package ForFlowDefs { flow def F; action def A; }
    package ForInterfaceDefs { interface def I; connection def Cn; connection def X :> I; }
    package ForItemDefs { item def It; part def P; attribute def AT; occurrence def X :> It; }
    package ForMetadataDefs { metadata def M; item def It; }
    package ForOccurrenceDefs { occurrence def O; part def P; attribute def AT; }
    package ForPartDefs { part def P; connection def Cn; item def It; item def X :> P; }
    package ForPortDefs { port def Q; part def P; }
    package ForRenderingDefs { rendering def Rd; part def P; part def X :> Rd; }
    package ForRequirementDefs { requirement def R; concern def Cc; constraint def Ct; constraint def X :> R; }
    package ForStateDefs { state def S; action def A; action def X :> S; }
    package ForUseCaseDefs { use case def U; case def K; case def X :> U; }
    package ForVerificationCaseDefs { verification def Vc; case def K; case def X :> Vc; }
    package ForViewDefs { view def Vw; part def P; part def X :> Vw; }
    package ForViewpointDefs { viewpoint def Vp; requirement def R; requirement def X :> Vp; }

    // Scope: owned, imported only, or both; an alias makes Local a member twice.
    package Imports { public import ForPartDefs::*; part def Local; alias LocalAlias for Local; }

    // Names: a short name is a name too. Two definitions with one name, both part definitions: whether
    // a namespace may hold them (whether distinguishability considers the metaclass) is an open
    // question; the backends load them, and a map refuses the name either way.
    package ShortNames { part def <w> Wheel; }
    package Clash { connection def Twin; view def Twin; }

    // Aliases across an import: a package's own alias for a definition it imports, and an imported alias
    // for a definition the package owns. A map's keys are every name a definition has in the namespace.
    package Aliased { public import ForPartDefs::*; alias Primary for ForPartDefs::P; }
    package Owner { part def Wheel; public import Aliases::*; }
    package Aliases { alias Rim for Owner::Wheel; }
}

Scopes.text:
package Scopes {
    part def P;
    part def Base { part a : P; protected part b : P; private part c : P; }
    part def Derived :> Base { part d : P; part :>> a; private part e : P; }
    part instance : Derived { part f : P; }

    // A supertype that imports a feature: Heir inherits q1 by name, but q1 is not a feature of Heir.
    package Lib { part def Q { part q1 : P; } }
    part def Importer { public import Lib::Q::*; part own : P; }
    part def Heir :> Importer;

    // A conjugated port definition: its original type's features are its inherited features.
    port def Pt { in item i; out item o; }
}

