MetaDefs.text:
package MetaDefs {
    metadata def N;
    metadata def M {
        attribute level : ScalarValues::Integer;
        metadata n : N;
        @N;
    }
    metadata def Tagged :> M;
    part def P {
        metadata m : M { :>> level = 1; metadata inner : N; }
    }
    part def Q :> P;
}

Typing.text:
package Typing {
    part def Vehicle;
    part def Car :> Vehicle;
    part def Engine;
    port def Plug;
    part def Wheel;
    part def Frame {
        attribute mass : ScalarValues::Real;
        part wheels : Wheel[4];
        part engine : Engine;
    }
    part def Body :> Frame {
        attribute :>> mass;
        part frontWheels :> wheels;
        ref part spare ::> wheels;
        part motor :> engine;
    }
    part def Truck :> Body { attribute :>> mass; }
    part def Battery { port powerOut : Plug; }
    part def Pack { part battery : Battery; port output :> battery.powerOut; }
}

Values.text:
package Values {
    private import SI::*;
    part def Car;
    part def Settings {
        attribute count = 4;
        attribute ratio = 0.5;
        attribute enabled = true;
        attribute label = "front";
        attribute offset = -5;
        attribute mass = 1500 [kg];
        attribute drag = -5 [kg];
        attribute speed = 3 [m/s];
        attribute twice = 2 * count;
        attribute other = count;
        attribute none;
        attribute fallback default = 3;
        ref part car : Car;
        attribute isCar = car istype Car;
        attribute asCar = car as Car;
    }
    part def Tank { attribute level := 2; }
}

