package Bounds {
    part def W;
    part def V {
        attribute n : ScalarValues::Integer;
        part two : W[2];
        part upToThree : W[0..3];
        part atLeastOne : W[1..*];
        part many : W[*];
        part counted : W[n];
        part sorted : W[*] ordered;
        part sortedToo :> sorted;
        ref part plain : W;
    }
}

Behaviour.text:
package Behaviour {
    private import ScalarValues::*;
    item def Fuel;
    attribute def Sig;
    attribute def SubSig :> Sig;
    port def Socket { in item plugIn : Fuel; out attribute status : Sig; inout item exchange : Fuel; }
    action def Pump { in item fuelIn : Fuel; out item fuelOut : Fuel; attribute rate : Real; }
    action pump : Pump { in item fuelIn; }
    calc def Double { in x : Real; 2 * x }
    constraint def Positive { in x : Real; x > 0 }
    calc half { in x : Real; x / 2 }
    part def Wheel;
    part def Vehicle { part wheels : Wheel[4]; part frontWheels :> wheels[2]; part engine; }
    action def Listen { action acc accept sig : Sig; }
    state def Machine { entry; then off; state off; state on; transition t first off accept Sig then on; }
    state def Machine2 { state off; state on; first start then off; }
    state def Machine3 { entry; then on; state off; state on; first start then off; }
    state lamp { entry; then dark; state dark; state lit; }
}

